(() => {
  'use strict';
  const C=window.SlowlyCore,CFG=window.SLOWLY_CONFIG||{},LOCAL_KEY='slowly_demo_v2';
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>Number(n||0).toLocaleString('zh-CN',{minimumFractionDigits:0,maximumFractionDigits:2});
  const pct=(v,t)=>Math.max(0,Math.min(100,Math.round(Number(v||0)/Math.max(1,Number(t||1))*100)));
  const labelType={income:'收入',necessary:'必要支出',nonessential:'非必要支出',saving_in:'储蓄转入',saving_out:'储蓄转出'};
  const encouragement=['不用很快，今天往前一点就好。','少买一件东西，多留一点生活。','允许休息，也允许重新开始。','每个小选择，都在照顾未来的你。','秩序不是控制，而是给生活留出空间。'];
  let mode=null,user=null,supabase=null,state=null,tab=new URLSearchParams(location.search).get('tab')||'home',selectedDate=C.dateKey(),journalDate=C.dateKey(),monthOffset=0,journalMonthOffset=0,goalView='annual',journalSaveTimer=null,onboardStep=1,syncTimer=null,deferredPrompt=null;
  function toast(msg,bad=false){const el=$('#toast');el.textContent=msg;el.className=bad?'show bad':'show';clearTimeout(el._t);el._t=setTimeout(()=>el.className='',2600);}
  function loadLocal(){try{return C.migrate(JSON.parse(localStorage.getItem(LOCAL_KEY)||'null'));}catch{return C.newState();}}
  function persist(message){C.touch(state);localStorage.setItem(mode==='demo'?LOCAL_KEY:`slowly_cache_${user?.id||'cloud'}`,JSON.stringify(state));renderSync();if(mode==='cloud'){clearTimeout(syncTimer);syncTimer=setTimeout(syncCloud,700);}if(message)toast(message);}
  async function initCloud(){if(!CFG.supabaseUrl||!CFG.supabaseAnonKey)return false;try{const mod=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');supabase=mod.createClient(CFG.supabaseUrl,CFG.supabaseAnonKey);const {data}=await supabase.auth.getSession();if(data.session){user=data.session.user;mode='cloud';await loadCloud();}supabase.auth.onAuthStateChange(async(_,session)=>{if(session&&!user){user=session.user;mode='cloud';await loadCloud();render();}});return true;}catch(e){console.warn(e);return false;}}
  async function loadCloud(){let cached;try{cached=JSON.parse(localStorage.getItem(`slowly_cache_${user.id}`)||'null');}catch{}state=C.migrate(cached||C.newState());if(!navigator.onLine)return;const {data,error}=await supabase.from('app_snapshots').select('data,revision,updated_at').eq('user_id',user.id).maybeSingle();if(error){toast('云端读取失败，已使用本地缓存',true);return;}if(data?.data)state=C.merge(state,C.migrate(data.data));await pushCloud();}
  async function pushCloud(){const payload={user_id:user.id,data:state,revision:state.revision,updated_at:new Date().toISOString()};const {error}=await supabase.from('app_snapshots').upsert(payload,{onConflict:'user_id'});if(error)throw error;localStorage.setItem(`slowly_cache_${user.id}`,JSON.stringify(state));}
  async function syncCloud(){if(mode!=='cloud'||!navigator.onLine){renderSync();return;}renderSync('syncing');try{const {data,error}=await supabase.from('app_snapshots').select('data').eq('user_id',user.id).maybeSingle();if(error)throw error;if(data?.data)state=C.merge(state,C.migrate(data.data));await pushCloud();render();toast('已与云端同步');}catch(e){console.error(e);renderSync('pending');toast('同步暂未完成，记录已安全保存在本机',true);}}
  function renderSync(status){const el=$('#syncState');if(!el)return;const online=navigator.onLine;if(mode==='demo')el.innerHTML='<span class="dot local"></span>本地演示';else if(status==='syncing')el.innerHTML='<span class="dot pulse"></span>同步中';else if(!online||status==='pending')el.innerHTML='<span class="dot warn"></span>待同步';else el.innerHTML='<span class="dot"></span>已同步';}
  function enterDemo(){mode='demo';localStorage.setItem('slowly_mode','demo');state=loadLocal();render();}
  function authView(cloudReady){return `<main class="auth-shell"><section class="auth-art"><div class="logo-mark">慢</div><p class="eyebrow">365天生活重建</p><h1>少买一点，<br>多活一点。</h1><p>每天 3–5 分钟，轻轻整理财务、物品和生活。</p></section><section class="auth-card"><h2>${cloudReady?'登录你的慢慢来':'本地演示模式'}</h2>${cloudReady?`<form id="authForm"><label class="field">邮箱<input type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label><label class="field">密码<input type="password" name="password" required minlength="6" autocomplete="current-password" placeholder="至少6位"></label><button class="btn wide" name="action" value="login">登录</button><button class="btn soft wide" name="action" value="signup">注册新账号</button></form><div class="divider"><span>或</span></div>`:'<p class="note">未配置 Supabase。演示记录只保存在当前浏览器，不会进入正式账号。</p>'}<button class="btn ghost wide" id="demoBtn">进入独立本地演示</button><p class="micro">继续即表示你理解：本地演示无法跨设备同步。</p></section></main>`;}
  function onboard(){const p=state.profile,s=state.settings;const titles=['从哪一天开始？','今年想多存多少钱？','想让多少件物品找到更好去处？','此刻最想改善什么？','准备好了'];let body='';if(onboardStep===1)body=`<label class="field">挑战开始日期<input type="date" name="startDate" value="${s.startDate}" required></label><p class="note">365天从你的真实开始日计算，不必等到周一或新年。</p>`;if(onboardStep===2)body=`<label class="field">年度储蓄目标（元）<input type="number" name="savingGoal" value="${s.savingGoal}" min="0" step="100" required></label>`;if(onboardStep===3)body=`<label class="field">年度断舍离目标（件）<input type="number" name="declutterGoal" value="${s.declutterGoal}" min="1" required></label>`;if(onboardStep===4)body=`<div class="choice-grid">${['财务与储蓄','空间与物品','健康与精力','学习与职业','关系与情绪'].map(x=>`<label class="choice"><input type="radio" name="focus" value="${x}" ${p.focus===x?'checked':''}><span>${x}</span></label>`).join('')}</div>`;if(onboardStep===5)body=`<div class="ready"><span>🌱</span><h3>Day 1 不需要完美</h3><p>已为你生成 12 个月计划和 52 周挑战。今天完成三件小事，就已经很好。</p></div>`;return `<main class="onboard"><section class="onboard-card"><div class="steps">${titles.map((_,i)=>`<i class="${i<onboardStep?'on':''}"></i>`).join('')}</div><p class="eyebrow">第 ${onboardStep} / 5 步</p><h1>${titles[onboardStep-1]}</h1><form id="onboardForm">${body}<div class="form-actions">${onboardStep>1?'<button class="btn ghost" type="button" id="onboardBack">返回</button>':''}<button class="btn" type="submit">${onboardStep===5?'进入我的 Day 1':'继续'}</button></div></form></section></main>`;}
  const card=(x,cls='')=>`<section class="card ${cls}">${x}</section>`, section=x=>`<div class="section-title"><h2>${x}</h2></div>`, progress=(v,t)=>`<div class="progress" aria-label="${pct(v,t)}%"><i style="width:${pct(v,t)}%"></i></div>`;
  function shell(content){return `<div class="app-shell"><header class="top"><button class="brand" data-tab="home"><span>慢</span><div>慢慢来<small>少买一点，多活一点</small></div></button><div class="top-actions"><span id="syncState" class="sync"></span><button class="icon-btn" data-action="install" aria-label="安装应用">↧</button></div></header><main>${content}</main>${nav()}</div><div id="modalRoot"></div>`;}
  function nav(){return `<nav class="nav" aria-label="主导航">${[['home','⌂','首页'],['plan','◇','计划'],['journal','✎','日记'],['money','¥','财务'],['me','○','我的']].map(([id,icon,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><b>${icon}</b><span>${name}</span></button>`).join('')}</nav>`;}
  function home(){
    const day=C.challengeDay(state),tasks=C.tasksFor(state,selectedDate),done=tasks.filter(Boolean).length,actions=C.occurrencesForDate(state,selectedDate),actionDone=actions.filter(x=>x.occurrenceStatus==='已完成').length,checked=Object.values(state.checkins).filter(x=>x.tasks.filter(Boolean).length>=3).length,remain=Math.max(0,365-day),week=Math.min(52,Math.ceil(day/7)),challenge=state.weeklyChallenges[week-1],saving=C.savingTotal(state),streak=C.streak(state);
    const d=new Date();d.setMonth(d.getMonth()+monthOffset);const yy=d.getFullYear(),mm=d.getMonth(),last=new Date(yy,mm+1,0).getDate(),blank=(new Date(yy,mm,1).getDay()+6)%7;
    return `<section class="welcome"><div><p class="eyebrow">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</p><h1>${esc(state.profile.nickname)}，今天也慢慢来。</h1><p>${encouragement[day%encouragement.length]}</p></div><div class="day-orbit"><b>${day}</b><span>DAY</span></div></section>
    <div class="metric-grid"><div><span>年度进度</span><b>${pct(day,365)}%</b>${progress(day,365)}<small>还剩 ${remain} 天</small></div><div><span>连续达标</span><b>${streak} 天</b><small>累计达标 ${checked} 天</small></div><div><span>累计储蓄</span><b>¥${money(saving)}</b><small>目标 ¥${money(state.settings.savingGoal)}</small></div></div>
    ${section('今日待办')}${card(`<div class="card-head"><div><b>${selectedDate===C.dateKey()?'今天':selectedDate} · ${actions.length} 项</b><p>已完成 ${actionDone} 项</p></div><input class="date-compact" id="actionDate" type="date" value="${selectedDate}"></div>${progress(actionDone,Math.max(1,actions.length))}<div class="action-list">${actions.length?actions.map(actionRow).join(''):'<div class="empty compact">今天还没有待办，给自己留一点呼吸。</div>'}</div><div class="inline-actions"><button class="btn small" data-open="task">＋ 添加任务</button><button class="btn small soft" data-open="doneTask">＋ 记录已完成</button></div>`) }
    ${section('今天，做一点就很好')}${card(`<div class="card-head"><div><b>每日五项</b><p>完成3项达标 · 5项额外奖励</p></div><input class="date-compact" id="habitDate" type="date" value="${selectedDate}" min="${state.settings.startDate}" max="${C.dateKey()}"></div>${progress(done,5)}<div class="task-list">${state.settings.taskLabels.map((x,i)=>`<label class="task ${tasks[i]?'done':''}"><input type="checkbox" data-checkin="${i}" ${tasks[i]?'checked':''}><span class="task-check">✓</span><span>${esc(x)}</span></label>`).join('')}</div><div class="kind-message">${done>=3?'今天已经达标了。剩下的，是礼物，不是任务。':'先选一件最容易的，完成它就很好。'}</div>`) }
    ${section('本周挑战')}${card(`<div class="challenge"><div class="week-no">W${week}</div><div><p>第 ${week} 周</p><h3>${esc(challenge?.title||'年度收尾')}</h3></div><button class="btn ${challenge?.completed?'soft':''}" data-week="${challenge?.id}">${challenge?.completed?'已完成':'完成 +20'}</button></div>`) }
    ${section('打卡日历')}${card(`<div class="calendar-head"><button class="icon-btn" data-month="-1">‹</button><b>${yy}年${mm+1}月</b><button class="icon-btn" data-month="1">›</button></div><div class="calendar"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span>${'<i></i>'.repeat(blank)}${Array.from({length:last},(_,i)=>{const k=`${yy}-${String(mm+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,n=C.tasksFor(state,k).filter(Boolean).length;return `<button data-date="${k}" class="${n===5?'great':n>=3?'good':''} ${k===selectedDate?'selected':''}">${i+1}</button>`}).join('')}</div><div class="legend"><span><i class="l1"></i>达标</span><span><i class="l2"></i>全部完成</span></div>`) }
    ${section('今日生活手账')}${card(`<button class="journal-cta" data-tab="journal"><span>✎</span><div><b>${state.dailyJournals.some(x=>x.date===C.dateKey())?'继续写今天':'写下今天的一句话'}</b><small>完成事项会自动带入，不必重复记录</small></div><em>›</em></button>`)}
    ${section('快速记录')}<div class="quick-grid"><button data-open="transaction"><span>¥</span>记一笔消费</button><button data-open="wish"><span>♡</span>添加购物愿望</button><button data-open="declutter"><span>♻</span>记录断舍离</button><button data-tab="items"><span>□</span>物品与空间</button></div>`;
  }
  function actionRow(t){const done=t.occurrenceStatus==='已完成';return `<div class="action-row ${done?'done':''}"><button class="action-check" data-task-status="${t.id}" data-date="${selectedDate}" aria-label="${done?'取消完成':'完成任务'}">${done?'✓':''}</button><div><b>${esc(t.title)}</b><small>${esc(t.category)}${t.goalId?' · '+esc(state.goalNodes.find(g=>g.id===t.goalId)?.title||'关联目标'):''}${t.estimatedMinutes?' · '+t.estimatedMinutes+'分钟':''}</small></div><span class="priority p${t.priority}">${t.priority>=2?'重要':'普通'}</span><button class="more" data-task-menu="${t.id}">•••</button></div>`;}
  function plan(){const levels={annual:'年度',monthly:'月度',weekly:'每周',daily:'今日'},nodes=state.goalNodes.filter(g=>g.level===goalView).sort((a,b)=>a.sortOrder-b.sortOrder);return `<section class="page-intro"><p class="eyebrow">目标拆解</p><h1>把远方，拆成今天能走的一小步。</h1></section><div class="segmented">${Object.entries(levels).map(([k,v])=>`<button data-goal-view="${k}" class="${goalView===k?'active':''}">${v}</button>`).join('')}</div><div class="goal-tree">${nodes.length?nodes.map(goalNodeCard).join(''):'<div class="empty-card">这一层还没有目标。</div>'}</div><button class="add-row" data-open="goalNode">＋ 添加${levels[goalView]}目标</button>${section('目标完成历史')}${card(state.goalHistory.length?state.goalHistory.slice(-8).reverse().map(h=>{const g=state.goalNodes.find(x=>x.id===h.goalId);return `<div class="history-row"><span>${esc(h.changedAt.slice(0,10))}</span><b>${esc(g?.title||'已删除目标')}</b><em>${esc(h.status)}</em></div>`;}).join(''):'<div class="empty compact">完成目标后，足迹会留在这里。</div>')}`;}
  function goalNodeCard(g){const p=C.goalProgress(state,g.id),children=state.goalNodes.filter(x=>x.parentId===g.id).sort((a,b)=>a.sortOrder-b.sortOrder);return card(`<div class="card-head"><div><span class="tag">${esc({annual:'年度',monthly:'月度',weekly:'每周'}[g.level]||'行动')}</span><h3>${esc(g.title)}</h3></div><button class="more" data-edit-goal-node="${g.id}">编辑</button></div><p class="goal-meta">${esc(g.category||'生活')} · ${esc({numeric:'数值型',task:'任务型',milestone:'里程碑型',habit:'习惯型'}[g.progressType]||'任务型')} · ${esc(g.status)}</p><div class="goal-number"><b>${p.percent}%</b><span>${money(p.current)} / ${money(p.target)} ${esc(g.unit||'项')}</span></div>${progress(p.current,p.target)}${children.length?`<div class="child-goals">${children.slice(0,4).map(x=>`<button data-open-child="${x.level}"><span>${esc(x.title)}</span><em>${C.goalProgress(state,x.id).percent}%</em></button>`).join('')}</div>`:''}`,'goal-node');}
  function goalProgress(g){if(g.category==='财务')return C.savingTotal(state);if(g.category==='断舍离')return state.declutter.length;if(g.unit==='周')return state.weeklyChallenges.filter(x=>x.completed).length;if(g.unit==='小时')return state.learningSessions.reduce((s,x)=>s+Number(x.minutes||0)/60,0);return Number(g.current||0);}
  function journal(){
    const d=new Date();d.setMonth(d.getMonth()+journalMonthOffset);const yy=d.getFullYear(),mm=d.getMonth(),last=new Date(yy,mm+1,0).getDate(),blank=(new Date(yy,mm,1).getDay()+6)%7;
    const saved=state.dailyJournals.find(x=>x.date===journalDate),draft=state.journalDrafts.find(x=>x.date===journalDate),j={mood:'平静',whatHappened:'',achievement:'',gratitude:'',tomorrowPlan:'',tomorrow1:'',tomorrow2:'',tomorrow3:'',...(saved||draft||{})};
    const completed=C.occurrencesForDate(state,journalDate).filter(x=>x.occurrenceStatus==='已完成'),images=state.journalImages.filter(x=>x.journalId===(saved?.id||j.id));
    const query=new URLSearchParams(location.search).get('q')||'',moodFilter=new URLSearchParams(location.search).get('mood')||'',history=state.dailyJournals.filter(x=>(!query||JSON.stringify(x).includes(query))&&(!moodFilter||x.mood===moodFilter)).sort((a,b)=>b.date.localeCompare(a.date));
    return `<section class="page-intro journal-intro"><p class="eyebrow">生活手账</p><h1>把普通的一天，也好好收进生活里。</h1><p id="journalSaveState">等待输入</p></section>
    <div class="journal-layout"><aside>${card(`<div class="calendar-head"><button class="icon-btn" data-journal-month="-1">‹</button><b>${yy}年${mm+1}月</b><button class="icon-btn" data-journal-month="1">›</button></div><div class="calendar journal-calendar"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span>${'<i></i>'.repeat(blank)}${Array.from({length:last},(_,i)=>{const k=`${yy}-${String(mm+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,has=state.dailyJournals.some(x=>x.date===k);return `<button data-journal-date="${k}" class="${has?'has-note':''} ${k===journalDate?'selected':''}">${i+1}</button>`;}).join('')}</div>`)}${section('历史日记')}${card(`<div class="filters"><input id="journalSearch" placeholder="搜索关键词" value="${esc(query)}"><select id="journalMood"><option value="">全部心情</option>${['开心','平静','疲惫','焦虑','难过'].map(x=>`<option ${moodFilter===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="journal-history">${history.slice(0,8).map(x=>`<button data-journal-date="${x.date}"><b>${x.date}</b><span>${esc(x.mood||'未记录心情')}</span><small>${esc((x.whatHappened||x.achievement||'只留下一点心情').slice(0,32))}</small></button>`).join('')||'<div class="empty compact">还没有日记。</div>'}</div><button class="add-inline" id="exportJournals">导出日记</button>`)}</aside>
    <section class="journal-paper"><form id="journalForm"><div class="journal-date"><span>${new Date(journalDate+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><input type="hidden" name="date" value="${journalDate}"></div><label class="mood-line">今日心情<select name="mood">${['开心','平静','疲惫','焦虑','难过'].map(x=>`<option ${j.mood===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="journal-field"><span>今天发生了什么</span><textarea name="whatHappened" placeholder="哪怕只写一句话也很好">${esc(j.whatHappened)}</textarea></label>
    <div class="completed-reference"><b>今日完成事项</b>${completed.length?completed.map(x=>`<div><span>✓ ${esc(x.title)}</span><small>${esc(x.category)} · ${x.completedAt?new Date(x.completedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'已完成'}${x.goalId?' · '+esc(state.goalNodes.find(g=>g.id===x.goalId)?.title||'目标'):''}</small></div>`).join(''):'<p>今天的完成事项会自动出现在这里。</p>'}</div>
    <div class="two"><label class="journal-field"><span>今日小成就</span><textarea name="achievement">${esc(j.achievement)}</textarea></label><label class="journal-field"><span>今日感恩</span><textarea name="gratitude">${esc(j.gratitude)}</textarea></label></div>
    <label class="journal-field"><span>明日计划</span><textarea name="tomorrowPlan">${esc(j.tomorrowPlan)}</textarea></label><div class="tomorrow-three"><b>明天最重要的 3 件事</b>${[1,2,3].map(i=>`<input name="tomorrow${i}" value="${esc(j['tomorrow'+i])}" placeholder="${i}. 一件重要的小事">`).join('')}<button class="btn small soft" type="button" id="addTomorrow">添加到明日待办</button></div>
    <div class="journal-photos"><b>今日照片</b><div id="photoPreview">${images.map(x=>`<figure><img data-image-id="${x.id}" src="${x.dataUrl||''}" alt="${esc(x.name)}"><button type="button" data-remove-image="${x.id}">×</button></figure>`).join('')}</div><label class="photo-add">＋ 添加照片<input id="journalPhoto" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><small>支持 JPG、PNG、WebP，单张不超过 5MB</small></div>
    <div class="form-actions">${saved?'<button class="btn ghost danger" type="button" id="deleteJournal">删除日记</button>':''}<button class="btn" type="submit">保存日记 +3</button></div></form></section></div>`;
  }
  function moneyPage(){const t=C.totals(state),spend=(t.necessary||0)+(t.nonessential||0),saving=C.savingTotal(state),month=C.dateKey().slice(0,7),monthTx=state.transactions.filter(x=>x.date?.startsWith(month));const mi=monthTx.filter(x=>x.type==='income').reduce((s,x)=>s+Number(x.amount),0),me=monthTx.filter(x=>['necessary','nonessential'].includes(x.type)).reduce((s,x)=>s+Number(x.amount),0);return `<section class="page-intro"><p class="eyebrow">轻量财务</p><h1>钱花向哪里，生活就走向哪里。</h1></section><div class="metric-grid money"><div><span>实际储蓄</span><b>¥${money(saving)}</b><small>${pct(saving,state.settings.savingGoal)}% 年度目标</small></div><div><span>本月收入</span><b>¥${money(mi)}</b><small>支出 ¥${money(me)}</small></div><div><span>累计非必要</span><b>¥${money(t.nonessential)}</b><small>总支出 ¥${money(spend)}</small></div></div>${card(`<div class="card-head"><div><b>年度储蓄目标</b><p>¥${money(saving)} / ¥${money(state.settings.savingGoal)}</p></div><button class="more" data-tab="me">调整</button></div>${progress(saving,state.settings.savingGoal)}<p class="micro">按当前进度预计：${saving>0?estimateDate(saving):'记录第一笔储蓄后计算'}</p>`) }
    <div class="split-title">${section('收支记录')}<button class="btn small" data-open="transaction">＋ 记一笔</button></div>${card(`<div class="filters"><select id="txFilter"><option value="all">全部类型</option>${Object.entries(labelType).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><input id="txMonth" type="month" value="${month}"></div><div id="txList">${txRows(state.transactions)}</div>`) }
    ${section('消费结构')}${card(chartBars([['必要支出',t.necessary,'#71866f'],['非必要支出',t.nonessential,'#e8c7a8'],['储蓄转入',t.saving_in,'#a9b9a5']]))}
    <div class="split-title">${section('72小时冷静期')}<button class="btn small soft" data-open="wish">＋ 添加愿望</button></div>${card(state.wishes.length?state.wishes.map(w=>wishRow(w)).join(''):'<div class="empty">想买时先放在这里，给心情一点时间。</div>')}
    ${section('不消费日历')}${card(`<p class="note">只有主动确认才算“不消费日”，没有记录不会自动判定。</p><div class="confirm-row"><input type="date" id="noSpendDate" value="${C.dateKey()}" max="${C.dateKey()}"><button class="btn soft" id="confirmNoSpend">${state.noSpendDays[C.dateKey()]?'已确认':'确认今天无非必要消费'}</button></div><p class="micro">今年已主动确认 ${Object.values(state.noSpendDays).filter(Boolean).length} 天</p>`)}${section('物品与空间')}${card(`<button class="journal-cta" data-tab="items"><span>□</span><div><b>物品、库存与断舍离</b><small>原有记录和功能完整保留</small></div><em>›</em></button>`)}`;}
  function estimateDate(saving){const elapsed=Math.max(1,C.challengeDay(state)),daily=saving/elapsed,left=Math.max(0,state.settings.savingGoal-saving),d=new Date();d.setDate(d.getDate()+Math.ceil(left/Math.max(.01,daily)));return d.toLocaleDateString('zh-CN');}
  function txRows(list){const filter=$('#txFilter')?.value||'all',month=$('#txMonth')?.value||'';const rows=[...list].filter(x=>(filter==='all'||x.type===filter)&&(!month||x.date.startsWith(month))).sort((a,b)=>b.date.localeCompare(a.date));return rows.length?rows.map(x=>`<div class="record"><div class="record-icon">${['income','saving_in'].includes(x.type)?'+':'−'}</div><div><b>${esc(x.category||labelType[x.type])}</b><small>${esc(x.date)} · ${esc(x.note||'无备注')}</small></div><strong class="${['income','saving_in'].includes(x.type)?'positive':''}">${['income','saving_in'].includes(x.type)?'+':'−'}¥${money(x.amount)}</strong><button class="more" data-edit="transactions:${x.id}">编辑</button></div>`).join(''):'<div class="empty">没有符合条件的记录。</div>';}
  function wishRow(w){const end=new Date(w.coolUntil),hours=Math.max(0,Math.ceil((end-Date.now())/3600000));return `<div class="wish"><div><b>${esc(w.name)}</b><small>¥${money(w.price)} · ${esc(w.reason||'未填写原因')}</small></div><span class="tag ${w.decision==='等待'&&hours?'warm':''}">${w.decision==='等待'?(hours?`还剩${hours}小时`:'可做决定'):esc(w.decision)}</span><button class="more" data-edit="wishes:${w.id}">处理</button></div>`;}
  function items(){const sold=state.declutter.reduce((s,x)=>s+Number(x.recovered||0),0),used=state.inventory.filter(x=>x.status==='已用完').length;return `<section class="page-intro"><p class="eyebrow">物品与空间</p><h1>留下真正服务生活的东西。</h1></section><div class="metric-grid"><div><span>已处理</span><b>${state.declutter.length} 件</b><small>目标 ${state.settings.declutterGoal} 件</small></div><div><span>回收金额</span><b>¥${money(sold)}</b><small>来自出售物品</small></div><div><span>已经用完</span><b>${used} 件</b><small>用完再买</small></div></div>${section('断舍离记录')}<button class="add-row" data-open="declutter">＋ 记录一件已处理物品</button>${card(state.declutter.length?state.declutter.map(x=>itemRow('declutter',x)).join(''):'<div class="empty">不是为了丢，而是让合适的物品去合适的地方。</div>')}${section('物品库存 · 用完再买')}<button class="add-row" data-open="inventory">＋ 添加库存物品</button>${card(state.inventory.length?state.inventory.map(x=>itemRow('inventory',x)).join(''):'<div class="empty">先记录常囤货的物品，减少重复购买。</div>')}`;}
  function itemRow(kind,x){return `<div class="record"><div class="record-icon">${kind==='declutter'?'♻':'□'}</div><div><b>${esc(x.name)}</b><small>${esc(x.category)} · ${esc(kind==='declutter'?x.method:x.status)}</small></div>${kind==='declutter'?`<strong>¥${money(x.recovered)}</strong>`:''}<button class="more" data-edit="${kind}:${x.id}">编辑</button></div>`;}
  function me(){const pts=C.points(state),level=Math.floor(Math.max(0,pts)/100)+1,total=state.pointEvents.reduce((s,x)=>s+Number(x.points),0);return `<section class="profile-hero"><div class="avatar">${esc(state.profile.nickname.slice(0,1))}</div><div><p class="eyebrow">LEVEL ${level}</p><h1>${esc(state.profile.nickname)}</h1><p>${esc(state.profile.focus)}</p></div><button class="more" data-open="settings">设置</button></section>${card(`<div class="level"><div><span>可用积分</span><b>${pts}</b></div><div><span>累计获得</span><b>${total}</b></div><div><span>下一等级</span><b>${100-pts%100}</b></div></div>${progress(pts%100,100)}`)}${section('奖励商店')}${card(state.rewards.filter(x=>x.active).map(r=>`<div class="reward"><div><b>${esc(r.title)}</b><small>${r.cost} 积分</small></div><button class="btn small soft" data-redeem="${r.id}" ${pts<r.cost?'disabled':''}>兑换</button></div>`).join('')+`<button class="add-inline" data-open="reward">＋ 自定义奖励</button>`)}${section('复盘')}<div class="quick-grid reviews"><button data-open="review" data-review-type="周复盘"><span>周</span>写周复盘</button><button data-open="review" data-review-type="月复盘"><span>月</span>写月复盘</button></div>${card(state.reviews.length?state.reviews.slice().reverse().map(r=>`<div class="review-row"><div><b>${esc(r.type)} · ${esc(r.date)}</b><p>${esc(r.summary||r.good||'已完成复盘')}</p></div><button class="more" data-edit="reviews:${r.id}">编辑</button></div>`).join(''):'<div class="empty">复盘不是打分，是听见自己。</div>')}${section('设置与数据')} ${card(`<button class="setting-row" data-open="settings"><span>个人资料与挑战设置</span><b>›</b></button><button class="setting-row" id="export"><span>导出 JSON 备份</span><b>↓</b></button><label class="setting-row"><span>导入备份（合并，不覆盖）</span><b>↑</b><input id="import" type="file" accept="application/json,.json" hidden></label><button class="setting-row" data-action="install"><span>安装到主屏幕</span><b>↧</b></button><button class="setting-row danger" id="logout"><span>${mode==='cloud'?'退出账号':'退出本地演示'}</span><b>›</b></button>`)}`;}
  function chartBars(items){const max=Math.max(1,...items.map(x=>x[1]));return `<div class="bar-chart">${items.map(([l,v,c])=>`<div><span>${l}</span><i><b style="width:${v/max*100}%;background:${c}"></b></i><strong>¥${money(v)}</strong></div>`).join('')}</div>`;}
  function render(){if(!mode){$('#app').innerHTML=authView(!!(CFG.supabaseUrl&&CFG.supabaseAnonKey));bindAuth();return;}if(!state.onboardingComplete){$('#app').innerHTML=onboard();bindOnboard();return;}const views={home,plan,journal,money:moneyPage,items,me};if(!views[tab])tab='home';$('#app').innerHTML=shell(views[tab]());bind();renderSync();}
  function bindAuth(){const d=$('#demoBtn');if(d)d.onclick=enterDemo;const f=$('#authForm');if(f)f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f),action=e.submitter?.value||'login',email=fd.get('email'),password=fd.get('password');const result=action==='signup'?await supabase.auth.signUp({email,password}):await supabase.auth.signInWithPassword({email,password});if(result.error)return toast(result.error.message,true);if(action==='signup'&&!result.data.session)toast('注册成功，请到邮箱完成验证');};}
  function bindOnboard(){const b=$('#onboardBack');if(b)b.onclick=()=>{onboardStep--;render();};$('#onboardForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(onboardStep===1){state.settings.startDate=fd.get('startDate');state.annualGoals.forEach(g=>g.startDate=state.settings.startDate);}if(onboardStep===2){state.settings.savingGoal=Number(fd.get('savingGoal'));const g=state.annualGoals.find(x=>x.category==='财务');if(g)g.target=state.settings.savingGoal;}if(onboardStep===3){state.settings.declutterGoal=Number(fd.get('declutterGoal'));const g=state.annualGoals.find(x=>x.category==='断舍离');if(g)g.target=state.settings.declutterGoal;}if(onboardStep===4)state.profile.focus=fd.get('focus')||state.profile.focus;if(onboardStep<5){onboardStep++;render();}else{state.onboardingComplete=true;persist();render();}};}
  function bind(){
    $$('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;history.replaceState(null,'',`?tab=${tab}`);render();scrollTo(0,0);});
    $('#actionDate')?.addEventListener('change',e=>{selectedDate=e.target.value;render();});
    $$('[data-task-status]').forEach(x=>x.onclick=()=>{const current=C.occurrencesForDate(state,x.dataset.date).find(t=>t.id===x.dataset.taskStatus);C.setTaskStatus(state,x.dataset.taskStatus,x.dataset.date,current?.occurrenceStatus==='已完成'?'待办':'已完成');persist();render();});
    $$('[data-task-menu]').forEach(x=>x.onclick=()=>openModal('taskMenu',{id:x.dataset.taskMenu,date:selectedDate}));
    $$('[data-checkin]').forEach(x=>x.onchange=()=>{C.setCheckin(state,selectedDate,Number(x.dataset.checkin),x.checked);persist();render();});
    $('#habitDate')?.addEventListener('change',e=>{selectedDate=e.target.value;render();});$$('.calendar [data-date]').forEach(x=>x.onclick=()=>{selectedDate=x.dataset.date;render();});$$('[data-month]').forEach(x=>x.onclick=()=>{monthOffset+=Number(x.dataset.month);render();});
    $$('[data-week],[data-week-check]').forEach(x=>x.addEventListener(x.type==='checkbox'?'change':'click',()=>{const id=x.dataset.week||x.dataset.weekCheck,completed=x.type==='checkbox'?x.checked:!state.weeklyChallenges.find(w=>w.id===id)?.completed;C.setWeekly(state,id,completed);persist();render();}));
    $$('[data-open]').forEach(x=>x.onclick=()=>openModal(x.dataset.open,{month:x.dataset.monthReview,reviewType:x.dataset.reviewType}));$$('[data-edit]').forEach(x=>x.onclick=()=>{const [k,id]=x.dataset.edit.split(':');openModal(k==='transactions'?'transaction':k==='wishes'?'wish':k==='reviews'?'review':k,{id});});$$('[data-edit-goal]').forEach(x=>x.onclick=()=>openModal('goal',{id:x.dataset.editGoal}));
    $$('[data-goal-view]').forEach(x=>x.onclick=()=>{if(x.dataset.goalView==='daily'){tab='home';selectedDate=C.dateKey();history.replaceState(null,'','?tab=home');}else goalView=x.dataset.goalView;render();});$$('[data-open-child]').forEach(x=>x.onclick=()=>{goalView=x.dataset.openChild;render();scrollTo(0,0);});$$('[data-edit-goal-node]').forEach(x=>x.onclick=()=>openModal('goalNode',{id:x.dataset.editGoalNode}));
    $$('[data-journal-date]').forEach(x=>x.onclick=()=>{journalDate=x.dataset.journalDate;render();});$$('[data-journal-month]').forEach(x=>x.onclick=()=>{journalMonthOffset+=Number(x.dataset.journalMonth);render();});
    bindJournal();
    $$('[data-redeem]').forEach(x=>x.onclick=()=>redeem(x.dataset.redeem));
    $('#txFilter')?.addEventListener('change',()=>$('#txList').innerHTML=txRows(state.transactions));$('#txMonth')?.addEventListener('change',()=>$('#txList').innerHTML=txRows(state.transactions));
    $('#confirmNoSpend')?.addEventListener('click',()=>{const d=$('#noSpendDate').value;state.noSpendDays[d]=!state.noSpendDays[d];persist('已更新不消费日');render();});
    $('#export')?.addEventListener('click',exportData);$('#import')?.addEventListener('change',importData);$('#logout')?.addEventListener('click',logout);$$('[data-action="install"]').forEach(x=>x.onclick=installApp);
  }
  function bindJournal(){
    const f=$('#journalForm');if(!f)return;
    const draft=()=>{const data=Object.fromEntries(new FormData(f).entries());C.saveDraft(state,data);localStorage.setItem(mode==='demo'?LOCAL_KEY:`slowly_cache_${user?.id||'cloud'}`,JSON.stringify(state));const s=$('#journalSaveState');if(s)s.textContent=navigator.onLine?'已保存草稿':'离线草稿已保存';};
    f.oninput=()=>{const s=$('#journalSaveState');if(s)s.textContent='正在保存…';clearTimeout(journalSaveTimer);journalSaveTimer=setTimeout(draft,500);};
    f.onsubmit=e=>{e.preventDefault();C.saveJournal(state,Object.fromEntries(new FormData(f).entries()));persist('日记已保存');render();};
    $('#addTomorrow')?.addEventListener('click',()=>{const data=Object.fromEntries(new FormData(f).entries()),j=C.saveJournal(state,data);C.tomorrowTasks(state,j,[data.tomorrow1,data.tomorrow2,data.tomorrow3]);persist('已加入明日待办，不会重复创建');render();});
    $('#deleteJournal')?.addEventListener('click',async()=>{if(!confirm('确定删除这篇日记？关联任务不会被删除。'))return;const j=state.dailyJournals.find(x=>x.date===journalDate),paths=state.journalImages.filter(x=>x.journalId===j?.id&&x.storagePath).map(x=>x.storagePath);if(mode==='cloud'&&paths.length)await supabase.storage.from('journal-images').remove(paths);C.deleteJournal(state,journalDate);persist('日记已删除');render();});
    $('#journalPhoto')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)return toast('请选择 5MB 以内的 JPG、PNG 或 WebP',true);let j=state.dailyJournals.find(x=>x.date===journalDate);if(!j)j=C.saveJournal(state,{...Object.fromEntries(new FormData(f).entries()),date:journalDate});const id=C.uid('image'),record={id,journalId:j.id,name:file.name,mimeType:file.type,size:file.size,createdAt:C.iso(),updatedAt:C.iso()};if(mode==='cloud'){record.storagePath=`${user.id}/${j.id}/${id}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await supabase.storage.from('journal-images').upload(record.storagePath,file,{contentType:file.type,upsert:false});if(error)return toast('图片上传失败，日记文字和草稿仍已保留',true);}else record.dataUrl=await new Promise((ok,bad)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=bad;r.readAsDataURL(file);});state.journalImages.push(record);persist('照片已添加');render();});
    state.journalImages.filter(x=>x.storagePath).forEach(async x=>{const {data}=await supabase?.storage.from('journal-images').createSignedUrl(x.storagePath,3600)||{};const img=document.querySelector(`[data-image-id="${x.id}"]`);if(img&&data?.signedUrl)img.src=data.signedUrl;});
    $$('[data-remove-image]').forEach(x=>x.onclick=async()=>{const image=state.journalImages.find(i=>i.id===x.dataset.removeImage);if(mode==='cloud'&&image?.storagePath)await supabase.storage.from('journal-images').remove([image.storagePath]);C.remove(state,'journalImages',x.dataset.removeImage);persist('照片已移除');render();});
    $('#journalSearch')?.addEventListener('change',e=>{const p=new URLSearchParams(location.search);p.set('tab','journal');e.target.value?p.set('q',e.target.value):p.delete('q');history.replaceState(null,'','?'+p);render();});$('#journalMood')?.addEventListener('change',e=>{const p=new URLSearchParams(location.search);p.set('tab','journal');e.target.value?p.set('mood',e.target.value):p.delete('mood');history.replaceState(null,'','?'+p);render();});
    $('#exportJournals')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state.dailyJournals,null,2)],{type:'application/json'}),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=`慢慢来-日记-${C.dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);});
  }
  function modal(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2><button class="icon-btn" id="closeModal">×</button></header>${body}</section></div>`;$('#closeModal').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal();};}
  function closeModal(){$('#modalRoot').innerHTML='';}
  function formButtons(collection,id){return `<div class="form-actions">${id?`<button type="button" class="btn ghost danger" id="deleteRecord" data-col="${collection}" data-id="${id}">删除</button>`:''}<button class="btn" type="submit">保存</button></div>`;}
  function openModal(type,opt={}){
    let rec,title,html;
    if(type==='task'||type==='doneTask'){rec=state.actionTasks.find(x=>x.id===opt.id)||{title:'',description:'',category:'生活',goalId:'',plannedDate:selectedDate,priority:1,estimatedMinutes:'',actualMinutes:'',recurrence:{type:'none'}};title=type==='doneTask'?'记录一件已经完成的事':opt.id?'编辑任务':'添加今日任务';html=`<form id="modalForm"><label class="field">事项名称<input name="title" value="${esc(rec.title)}" required autofocus></label><label class="field">描述或备注<textarea name="description">${esc(rec.description)}</textarea></label><div class="two"><label class="field">分类<input name="category" value="${esc(rec.category)}"></label><label class="field">关联目标<select name="goalId"><option value="">不关联目标</option>${state.goalNodes.map(g=>`<option value="${g.id}" ${rec.goalId===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label></div><div class="two"><label class="field">${type==='doneTask'?'完成日期':'计划日期'}<input name="plannedDate" type="date" value="${rec.plannedDate||selectedDate}"></label><label class="field">优先级<select name="priority"><option value="1" ${rec.priority<2?'selected':''}>普通 · +2</option><option value="2" ${rec.priority>=2?'selected':''}>重要 · +5</option></select></label></div><div class="two"><label class="field">预计用时（分钟）<input name="estimatedMinutes" type="number" min="0" value="${rec.estimatedMinutes||''}"></label><label class="field">实际用时（分钟）<input name="actualMinutes" type="number" min="0" value="${rec.actualMinutes||''}"></label></div>${type==='task'? `<label class="field">重复规则<select name="recurrenceType"><option value="none">不重复</option><option value="daily" ${rec.recurrence?.type==='daily'?'selected':''}>每天</option><option value="weekdays" ${rec.recurrence?.type==='weekdays'?'selected':''}>工作日</option><option value="weekly" ${rec.recurrence?.type==='weekly'?'selected':''}>每周同一天</option><option value="custom" ${rec.recurrence?.type==='custom'?'selected':''}>自定义周期</option></select></label><label class="field">自定义间隔天数<input name="interval" type="number" min="1" value="${rec.recurrence?.interval||2}"></label>`:''}${formButtons('actionTasks',opt.id)}</form>`;}
    if(type==='taskMenu'){const t=state.actionTasks.find(x=>x.id===opt.id);title=t?.title||'任务操作';html=`<div class="task-menu"><button class="setting-row" id="editTask"><span>编辑任务</span><b>›</b></button><button class="setting-row" id="skipTask"><span>标记跳过</span><b>›</b></button><label class="field">延期到<input id="rescheduleDate" type="date" value="${C.addDays(opt.date,1)}"></label><button class="btn soft wide" id="rescheduleTask">确认延期</button><button class="setting-row danger" id="deleteTask"><span>删除任务定义</span><b>×</b></button></div>`;}
    if(type==='goalNode'){rec=state.goalNodes.find(x=>x.id===opt.id)||{title:'',description:'',category:'生活重建',level:goalView==='daily'?'weekly':goalView,parentId:'',progressType:'task',target:1,unit:'项',status:'进行中',sortOrder:state.goalNodes.length};title=opt.id?'编辑目标':'添加目标';const parents=state.goalNodes.filter(g=>({monthly:'annual',weekly:'monthly'}[rec.level]===g.level));html=`<form id="modalForm"><label class="field">目标标题<input name="title" value="${esc(rec.title)}" required></label><label class="field">说明<textarea name="description">${esc(rec.description||'')}</textarea></label><div class="two"><label class="field">层级<select name="level">${[['annual','年度'],['monthly','月度'],['weekly','每周']].map(([v,l])=>`<option value="${v}" ${rec.level===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">上级目标<select name="parentId"><option value="">无上级</option>${parents.map(g=>`<option value="${g.id}" ${rec.parentId===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label></div><div class="two"><label class="field">进度类型<select name="progressType">${[['numeric','数值型'],['task','任务型'],['milestone','里程碑型'],['habit','习惯型']].map(([v,l])=>`<option value="${v}" ${rec.progressType===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">状态<select name="status">${['进行中','已完成','已暂停'].map(x=>`<option ${rec.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="two"><label class="field">目标值<input name="target" type="number" min="0" value="${rec.target||0}"></label><label class="field">单位<input name="unit" value="${esc(rec.unit||'项')}"></label></div><label class="field">分类<input name="category" value="${esc(rec.category||'生活重建')}"></label>${formButtons('goalNodes',opt.id)}</form>`;}
    if(type==='transaction'){rec=state.transactions.find(x=>x.id===opt.id)||{type:'necessary',date:C.dateKey(),amount:'',category:'生活必需',note:''};title=opt.id?'编辑记录':'记一笔';html=`<form id="modalForm"><div class="two"><label class="field">类型<select name="type">${Object.entries(labelType).map(([v,l])=>`<option value="${v}" ${rec.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">金额<input name="amount" type="number" min="0.01" step="0.01" value="${rec.amount}" required></label></div><div class="two"><label class="field">分类<input name="category" value="${esc(rec.category)}" required></label><label class="field">日期<input name="date" type="date" value="${rec.date}" required></label></div><label class="field">备注<input name="note" value="${esc(rec.note)}" placeholder="可选"></label>${formButtons('transactions',opt.id)}</form>`;}
    if(type==='wish'){rec=state.wishes.find(x=>x.id===opt.id)||{name:'',price:'',reason:'',essential:false,decision:'等待'};title=opt.id?'处理购物愿望':'添加购物愿望';html=`<form id="modalForm"><label class="field">商品名称<input name="name" value="${esc(rec.name)}" required></label><div class="two"><label class="field">价格<input name="price" type="number" min="0" step="0.01" value="${rec.price}" required></label><label class="field">是否必需<select name="essential"><option value="false" ${!rec.essential?'selected':''}>非必需</option><option value="true" ${rec.essential?'selected':''}>必需</option></select></label></div><label class="field">为什么想买<textarea name="reason">${esc(rec.reason)}</textarea></label>${opt.id?`<label class="field">最终决定<select name="decision">${['等待','放弃','购买'].map(x=>`<option ${rec.decision===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}${formButtons('wishes',opt.id)}</form>`;}
    if(type==='declutter'){rec=state.declutter.find(x=>x.id===opt.id)||{name:'',category:'衣物鞋包',method:'出售',originalPrice:'',recovered:'',date:C.dateKey(),status:'已处理'};title=opt.id?'编辑断舍离':'记录断舍离';html=`<form id="modalForm"><label class="field">物品名称<input name="name" value="${esc(rec.name)}" required></label><div class="two"><label class="field">类别<select name="category">${['衣物鞋包','护肤彩妆','家居用品','数码设备','文具书籍','其他'].map(x=>`<option ${rec.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">处理方式<select name="method">${['出售','赠送','捐赠','回收'].map(x=>`<option ${rec.method===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="two"><label class="field">原价（可选）<input name="originalPrice" type="number" min="0" value="${rec.originalPrice}"></label><label class="field">回收金额<input name="recovered" type="number" min="0" value="${rec.recovered}"></label></div><label class="field">处理日期<input name="date" type="date" value="${rec.date}"></label>${formButtons('declutter',opt.id)}</form>`;}
    if(type==='inventory'){rec=state.inventory.find(x=>x.id===opt.id)||{name:'',category:'护肤彩妆',quantity:1,purchaseDate:'',status:'库存',replenish:false};title=opt.id?'编辑库存':'添加库存';html=`<form id="modalForm"><label class="field">物品名称<input name="name" value="${esc(rec.name)}" required></label><div class="two"><label class="field">类别<select name="category">${['衣物鞋包','护肤彩妆','家居用品','数码设备','文具书籍','其他'].map(x=>`<option ${rec.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">数量<input name="quantity" type="number" min="0" value="${rec.quantity}"></label></div><div class="two"><label class="field">购买日期<input name="purchaseDate" type="date" value="${rec.purchaseDate}"></label><label class="field">使用状态<select name="status">${['库存','正在使用','已用完','需要补货'].map(x=>`<option ${rec.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div>${formButtons('inventory',opt.id)}</form>`;}
    if(type==='goal'){rec=state.annualGoals.find(x=>x.id===opt.id)||{title:'',category:'个人成长',target:1,unit:'次',startDate:state.settings.startDate,endDate:'',status:'进行中'};title=opt.id?'编辑年度目标':'添加年度目标';html=`<form id="modalForm"><label class="field">目标标题<input name="title" value="${esc(rec.title)}" required></label><div class="two"><label class="field">分类<select name="category">${['财务','断舍离','个人成长','生活重建'].map(x=>`<option ${rec.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">状态<select name="status">${['进行中','已完成','已暂停'].map(x=>`<option ${rec.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="two"><label class="field">目标值<input name="target" type="number" min="0" value="${rec.target}"></label><label class="field">单位<input name="unit" value="${esc(rec.unit)}"></label></div>${formButtons('annualGoals',opt.id)}</form>`;}
    if(type==='review'){rec=state.reviews.find(x=>x.id===opt.id)||{type:opt.reviewType||'周复盘',date:C.dateKey(),good:'',hard:'',next:'',summary:''};title=rec.type;html=`<form id="modalForm"><input type="hidden" name="type" value="${rec.type}"><label class="field">日期<input name="date" type="date" value="${rec.date}"></label><label class="field">最开心的三件事<textarea name="good">${esc(rec.good)}</textarea></label><label class="field">最大的困难<textarea name="hard">${esc(rec.hard)}</textarea></label><label class="field">下阶段重点<textarea name="next">${esc(rec.next)}</textarea></label><label class="field">成长总结<textarea name="summary">${esc(rec.summary)}</textarea></label>${formButtons('reviews',opt.id)}</form>`;}
    if(type==='reward'){rec={title:'',cost:50,active:true};title='自定义奖励';html=`<form id="modalForm"><label class="field">奖励名称<input name="title" required></label><label class="field">所需积分<input name="cost" type="number" min="1" value="50" required></label>${formButtons('rewards')}</form>`;}
    if(type==='mood'){rec={mood:'平静',note:'',date:C.dateKey()};title='今日心情';html=`<form id="modalForm"><label class="field">此刻的心情<select name="mood">${['开心','平静','疲惫','焦虑','难过'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">想写下什么<textarea name="note"></textarea></label><input type="hidden" name="date" value="${C.dateKey()}">${formButtons('moodEntries')}</form>`;}
    if(type==='monthReview'){rec=state.monthlyPlans.find(x=>x.month===Number(opt.month));title=`M${opt.month} 月度复盘`;html=`<form id="modalForm"><label class="field">这月发生了什么<textarea name="review">${esc(rec.review)}</textarea></label>${formButtons('monthlyPlans',rec.id)}</form>`;}
    if(type==='settings'){rec=state.settings;title='设置';html=`<form id="modalForm"><label class="field">昵称<input name="nickname" value="${esc(state.profile.nickname)}"></label><div class="two"><label class="field">开始日期<input name="startDate" type="date" value="${rec.startDate}"></label><label class="field">默认货币<select name="currency"><option value="CNY">人民币 CNY</option></select></label></div><div class="two"><label class="field">储蓄目标<input name="savingGoal" type="number" min="0" value="${rec.savingGoal}"></label><label class="field">断舍离目标<input name="declutterGoal" type="number" min="1" value="${rec.declutterGoal}"></label></div><label class="field">非必要消费规则<textarea name="nonEssentialRule">${esc(rec.nonEssentialRule)}</textarea></label><fieldset><legend>每日任务（每行一项，固定5项）</legend><textarea name="taskLabels">${esc(rec.taskLabels.join('\n'))}</textarea></fieldset><label class="toggle"><input name="privacyMode" type="checkbox" ${rec.privacyMode?'checked':''}>隐藏敏感金额（预留隐私偏好）</label>${formButtons('settings')}</form>`;}
    modal(title,html);if(type==='taskMenu'){const t=state.actionTasks.find(x=>x.id===opt.id);$('#editTask').onclick=()=>{closeModal();openModal('task',{id:opt.id});};$('#skipTask').onclick=()=>{C.setTaskStatus(state,opt.id,opt.date,'已跳过');persist('任务已跳过');closeModal();render();};$('#rescheduleTask').onclick=()=>{C.rescheduleTask(state,opt.id,opt.date,$('#rescheduleDate').value);persist('任务已延期');closeModal();render();};$('#deleteTask').onclick=()=>{if(confirm('删除任务？已有的历史完成记录会保留。')){C.remove(state,'actionTasks',opt.id);persist('任务已删除');closeModal();render();}};}else bindModal(type,opt,rec);
  }
  function bindModal(type,opt,rec){
    $('#deleteRecord')?.addEventListener('click',e=>{if(confirm('确定删除这条记录？统计会立即重新计算。')){C.remove(state,e.currentTarget.dataset.col,e.currentTarget.dataset.id);persist('已删除');closeModal();render();}});
    $('#modalForm').onsubmit=e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.currentTarget).entries());
      if(type==='settings'){const labels=raw.taskLabels.split('\n').map(x=>x.trim()).filter(Boolean);if(labels.length!==5)return toast('每日任务必须正好5项',true);state.profile.nickname=raw.nickname||'慢慢';Object.assign(state.settings,{startDate:raw.startDate,savingGoal:Number(raw.savingGoal),declutterGoal:Number(raw.declutterGoal),nonEssentialRule:raw.nonEssentialRule,taskLabels:labels,privacyMode:!!raw.privacyMode});}
      else if(type==='task'||type==='doneTask'){const data={...raw,id:opt.id||rec.id||undefined,priority:Number(raw.priority),estimatedMinutes:Number(raw.estimatedMinutes||0),actualMinutes:Number(raw.actualMinutes||0),recurrence:{type:raw.recurrenceType||'none',interval:Number(raw.interval||1)}};if(type==='doneTask'){data.date=raw.plannedDate;C.recordCompleted(state,data);}else C.createTask(state,data);}
      else if(type==='goalNode'){const oldStatus=rec.status,obj={...rec,...raw,id:opt.id||rec.id||C.uid('goalnode'),target:Number(raw.target||0),sortOrder:Number(rec.sortOrder||state.goalNodes.length)};C.upsert(state.goalNodes,obj);if(oldStatus!==obj.status||(!opt.id&&obj.status==='已完成'))C.setGoalStatus(state,obj.id,obj.status);}
      else if(type==='monthReview'){rec.review=raw.review;rec.updatedAt=C.iso();if(raw.review&&!state.pointEvents.some(x=>x.key===`month_review:${rec.month}`))state.pointEvents.push({id:C.uid('pt'),key:`month_review:${rec.month}`,type:'月度财务复盘',points:30,ref:String(rec.month),createdAt:C.iso(),updatedAt:C.iso()});}
      else{const col={transaction:'transactions',wish:'wishes',declutter:'declutter',inventory:'inventory',goal:'annualGoals',review:'reviews',reward:'rewards',mood:'moodEntries'}[type],obj={...rec,...raw,id:opt.id||rec.id||C.uid(type)};['amount','price','originalPrice','recovered','quantity','target','cost'].forEach(k=>{if(k in obj)obj[k]=Number(obj[k]||0);});if(type==='wish'){obj.essential=raw.essential==='true';if(!opt.id){obj.addedAt=C.iso();obj.coolUntil=new Date(Date.now()+state.settings.calmHours*3600000).toISOString();obj.decision='等待';}}if(type==='review'&&!opt.id){const key=`review:${obj.type}:${obj.date}`;if(!state.pointEvents.some(x=>x.key===key))state.pointEvents.push({id:C.uid('pt'),key,type:obj.type,points:30,ref:obj.date,createdAt:C.iso(),updatedAt:C.iso()});}C.upsert(state[col],obj);}
      persist('已保存');closeModal();render();};
  }
  function redeem(id){const r=state.rewards.find(x=>x.id===id);if(!r||C.points(state)<r.cost)return;if(!confirm(`使用 ${r.cost} 积分兑换「${r.title}」？`))return;state.redemptions.push({id:C.uid('redeem'),rewardId:id,title:r.title,cost:r.cost,createdAt:C.iso(),updatedAt:C.iso()});persist('兑换成功，记得好好享受');render();}
  function exportData(){const blob=new Blob([JSON.stringify({app:'slowly',version:C.VERSION,exportedAt:C.iso(),data:state},null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`慢慢来-备份-${C.dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function importData(e){const file=e.target.files[0];if(!file)return;try{const incoming=C.validateBackup(JSON.parse(await file.text()));state=C.merge(state,incoming);persist('备份已安全合并');render();}catch(err){toast(`导入失败：${err.message}`,true);}e.target.value='';}
  async function logout(){if(mode==='cloud')await supabase.auth.signOut();localStorage.removeItem('slowly_mode');mode=null;user=null;state=null;render();}
  async function installApp(){if(deferredPrompt){deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;}else modal('安装到主屏幕',`<div class="install-help"><h3>iPhone / iPad</h3><p>在 Safari 中点“分享” → “添加到主屏幕”。</p><h3>Android</h3><p>在浏览器菜单中选择“安装应用”或“添加到主屏幕”。</p><button class="btn wide" id="gotIt">知道了</button></div>`),$('#gotIt').onclick=closeModal;}
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;});window.addEventListener('online',()=>{toast('网络已恢复，正在同步');syncCloud();});window.addEventListener('offline',()=>{renderSync('pending');toast('已离线，操作会保存在本机');});
  if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
  (async()=>{const ready=await initCloud();if(!mode&&localStorage.getItem('slowly_mode')==='demo'){mode='demo';state=loadLocal();}render();if(!ready&&CFG.supabaseUrl)toast('云端服务暂不可用，可使用本地演示',true);})();
})();

